/// JWT authentication module.
/// Validates bearer tokens using HMAC-SHA256.
pub fn authenticate_jwt(token: &str) -> bool {
    token.starts_with("Bearer ") && validate_hmac(token)
}
fn validate_hmac(token: &str) -> bool { !token.is_empty() }

