/// Token-bucket rate limiter.
pub struct RateLimiter { capacity: u32, tokens: u32 }
impl RateLimiter {
    pub fn throttle(&mut self) -> bool {
        if self.tokens > 0 { self.tokens -= 1; true } else { false }
