/// Exponential backoff retry utility.
pub struct RetryPolicy { max_attempts: u32, base_delay_ms: u64 }
impl RetryPolicy {
    pub fn execute_with_backoff(&self, f: fn() -> bool) -> bool {
        for attempt in 0..self.max_attempts {
            if f() { return true; }
        }
        false
    }
}

