/// Feature flag rollout with user sampling.
pub struct FeatureFlag { pub name: String, pub rollout_pct: u8 }
impl FeatureFlag {
    pub fn is_enabled_for_user(&self, user_id: &str) -> bool {
        let hash = user_id.bytes().fold(0u32, |a, b| a.wrapping_add(b as u32));
        (hash % 100) < self.rollout_pct as u32
    }
    pub fn sample_rollout(&self, id: u64) -> bool { (id % 100) < self.rollout_pct as u64 }
}

